def read(p):return json.loads(Path(p).read_text())
def write(name,x): (OUT/name).write_text(json.dumps(x,indent=2)+'\n')
def quantile(v,p):
 a=sorted(v);i=(len(a)-1)*p;lo=int(i);return a[lo]+(a[min(lo+1,len(a)-1)]-a[lo])*(i-lo)
def bootstrap(values):
 rng=random.Random(121212); n=len(values)
 if n<2:return {'families':n,'interval':None}
 samples=[statistics.mean(rng.choices(values,k=n))for _ in range(10000)]
 return {'families':n,'family_balanced_mean':statistics.mean(values),'percentile95':[quantile(samples,.025),quantile(samples,.975)],'scope':'Exploratory source-family bootstrap,10000 replicates; fixed fitted weights and simulation settings; no across-training-seed uncertainty.'}
def aggregate(panel,folder,protocol):
 spec=read(protocol);sc={s['scenario_id']:s for s in spec['scenarios']};out=[];initial={}
 for method in sorted(p for p in folder.iterdir()if p.is_dir()and(p/'summary.json').exists()):
  rr=read(method/'summary.json');assert read(method/'complete.json').get('completed',read(method/'complete.json').get('all_scored',False))
  groups=collections.defaultdict(list)
  for row in rr:
   s=sc[row['id']];row={**row,'panel':panel,'source_demo_id':s['source_demo_id'],'group':s.get('group','recovery'),'evidence':str(method/row['id'])};out.append(row);groups[row['group']].append(row)
   ep=read(method/row['id']/'episode.json');t=ep['initial_truth'];v=t['object_position_m']+t['object_quat_wxyz']+t['eef_position_m']
   if row['id'] in initial:assert max(abs(a-b)for a,b in zip(initial[row['id']],v))<1e-9
   else:initial[row['id']]=v
  for group,rows in groups.items():
   fam=collections.defaultdict(list)
   for a in rows:fam[a['source_demo_id']].append(int(a['success']))
   GROUPS.append({'panel':panel,'method':method.name,'group':group,'n':len(rows),'strict':sum(a['success']for a in rows),'supported_grasp_10mm':sum(a['supported_lift_10mm_3steps']for a in rows),'operational_place':sum(a['operational_placement']for a in rows),'median_final_position_mm':statistics.median(a['position_error_mm']for a in rows),'median_final_yaw_deg':statistics.median(a['yaw_error_deg']for a in rows),'median_yaw_reduction_deg':statistics.median(a['yaw_error_reduction_deg']for a in rows),'runtime_errors':sum(bool(a['errors'])for a in rows),'strict_family_bootstrap':bootstrap([statistics.mean(x)for x in fam.values()])})
 return out
